import React from 'react';
import { motion } from 'framer-motion';
import { FiBookOpen, FiUsers, FiAward, FiTarget } from 'react-icons/fi';

const About = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        delayChildren: 0.3,
        staggerChildren: 0.2
      }
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1
    }
  };

  return (
    <div className="page-transition">
      {/* Hero Section */}
      <motion.section 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6 }}
        className="bg-gradient-to-br from-primary-600 to-primary-800 text-white py-20 px-4"
      >
        <div className="container mx-auto text-center">
          <motion.h1
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="text-4xl md:text-5xl font-bold mb-6"
          >
            من نحن
          </motion.h1>
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.5, delay: 0.4 }}
            className="max-w-3xl mx-auto bg-white/10 backdrop-blur-sm p-6 rounded-xl border border-white/20"
          >
            <p className="text-xl leading-relaxed">
              منصة تعليمية عربية متكاملة تهدف إلى توفير تجربة تعليمية فريدة من نوعها للطلاب والمعلمين في جميع أنحاء العالم العربي
            </p>
          </motion.div>
        </div>
      </motion.section>

      {/* Mission Section */}
      <section className="py-16 px-4">
        <div className="container mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="text-center mb-16"
          >
            <h2 className="text-3xl font-bold mb-4 text-gray-900 dark:text-white">
              <span className="gradient-text">رسالتنا</span>
            </h2>
            <p className="text-xl text-gray-600 dark:text-gray-400 max-w-3xl mx-auto">
              تقديم تعليم عالي الجودة باللغة العربية بطريقة مبتكرة وتفاعلية، مما يساعد الطلاب على تحقيق أهدافهم التعليمية والمهنية.
            </p>
          </motion.div>

          <motion.div
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.3 }}
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8"
          >
            <motion.div variants={itemVariants} className="card hover-lift">
              <div className="flex justify-center mb-6">
                <div className="rounded-full bg-primary-100 dark:bg-primary-900/50 p-5 text-primary-600 dark:text-primary-400">
                  <FiBookOpen className="h-8 w-8" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-3 text-center text-gray-900 dark:text-white">تعليم عالي الجودة</h3>
              <p className="text-gray-600 dark:text-gray-400 text-center">
                نقدم محتوى تعليمي على يد نخبة من المعلمين المتميزين في جميع المجالات
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card hover-lift">
              <div className="flex justify-center mb-6">
                <div className="rounded-full bg-secondary-100 dark:bg-secondary-900/50 p-5 text-secondary-600 dark:text-secondary-400">
                  <FiUsers className="h-8 w-8" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-3 text-center text-gray-900 dark:text-white">مجتمع تعليمي</h3>
              <p className="text-gray-600 dark:text-gray-400 text-center">
                نبني مجتمعاً تعليمياً داعماً يساعد الطلاب على التفاعل والتعلم من بعضهم البعض
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card hover-lift">
              <div className="flex justify-center mb-6">
                <div className="rounded-full bg-accent-100 dark:bg-accent-900/50 p-5 text-accent-600 dark:text-accent-400">
                  <FiAward className="h-8 w-8" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-3 text-center text-gray-900 dark:text-white">اعتماد وموثوقية</h3>
              <p className="text-gray-600 dark:text-gray-400 text-center">
                نقدم شهادات معتمدة وموثوقة تساعد الطلاب في مسيرتهم التعليمية والمهنية
              </p>
            </motion.div>

            <motion.div variants={itemVariants} className="card hover-lift">
              <div className="flex justify-center mb-6">
                <div className="rounded-full bg-warning-100 dark:bg-warning-900/50 p-5 text-warning-600 dark:text-warning-400">
                  <FiTarget className="h-8 w-8" />
                </div>
              </div>
              <h3 className="text-xl font-bold mb-3 text-center text-gray-900 dark:text-white">أهداف طموحة</h3>
              <p className="text-gray-600 dark:text-gray-400 text-center">
                نسعى لتحقيق أهداف طموحة في مجال التعليم العربي وتطوير مهارات الطلاب
              </p>
            </motion.div>
          </motion.div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="py-16 px-4 bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800">
        <div className="container mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl font-bold mb-4 text-gray-900 dark:text-white">إنجازاتنا بالأرقام</h2>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
            <StatCard number="500+" label="دورة تعليمية" color="primary" delay={0} />
            <StatCard number="50+" label="معلم متميز" color="secondary" delay={0.1} />
            <StatCard number="10,000+" label="طالب مسجل" color="accent" delay={0.2} />
            <StatCard number="98%" label="نسبة الرضا" color="success" delay={0.3} />
          </div>
        </div>
      </section>

      {/* Team Section */}
      <section className="py-16 px-4">
        <div className="container mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl font-bold mb-4 text-gray-900 dark:text-white">
              <span className="gradient-text">فريق العمل</span>
            </h2>
            <p className="text-xl text-gray-600 dark:text-gray-400 max-w-3xl mx-auto">
              فريقنا المتميز يعمل بشغف لتقديم تجربة تعليمية فريدة من نوعها
            </p>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            <TeamMember 
              name="أحمد محمد" 
              role="المؤسس والمدير التنفيذي" 
              delay={0} 
            />
            <TeamMember 
              name="سارة علي" 
              role="مديرة المحتوى التعليمي" 
              delay={0.1} 
            />
            <TeamMember 
              name="محمد خالد" 
              role="مدير تطوير المنصة" 
              delay={0.2} 
            />
          </div>
        </div>
      </section>
    </div>
  );
};

// Stat Card Component
const StatCard = ({ number, label, color, delay }) => {
  const colorClasses = {
    primary: "from-primary-500 to-primary-700 shadow-primary-500/20",
    secondary: "from-secondary-500 to-secondary-700 shadow-secondary-500/20",
    accent: "from-accent-500 to-accent-700 shadow-accent-500/20",
    success: "from-success-500 to-success-700 shadow-success-500/20",
    warning: "from-warning-500 to-warning-700 shadow-warning-500/20"
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay }}
      viewport={{ once: true }}
      whileHover={{ y: -5, scale: 1.02 }}
      className={`bg-gradient-to-br ${colorClasses[color]} text-white rounded-xl p-8 text-center shadow-lg`}
    >
      <h3 className="text-4xl font-bold mb-2 animate-float">{number}</h3>
      <p className="text-lg opacity-90">{label}</p>
    </motion.div>
  );
};

// Team Member Component
const TeamMember = ({ name, role, delay }) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay }}
      viewport={{ once: true }}
      whileHover={{ y: -5 }}
      className="card text-center hover:shadow-highlight"
    >
      <div className="w-24 h-24 mx-auto mb-6 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full flex items-center justify-center text-white text-2xl font-bold">
        {name.charAt(0)}
      </div>
      <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">{name}</h3>
      <p className="text-gray-600 dark:text-gray-400 mb-4">{role}</p>
      <div className="flex justify-center space-x-3">
        <span className="badge-primary">التعليم</span>
        <span className="badge-secondary">التطوير</span>
      </div>
    </motion.div>
  );
};

export default About;
